__global__ void block_sum(const float* x, float* partial, int n) {
    __shared__ float s[256];
    int t = threadIdx.x;
    int i = blockIdx.x * blockDim.x + t;
    s[t] = (i < n) ? x[i] : [[b1]];
    [[b2]]

    for (int stride = blockDim.x / 2; stride >= 32; stride [[b3]]) {
        if (t < stride) s[t] += s[t + stride];
        __syncthreads();
    }

    if (t < 32) {
        float v = s[t];
        for (int offset = 16; offset > 0; offset /= 2)
            v += __shfl_down_sync(0xffffffff, v, [[b4]]);
        if (t == [[b5]]) partial[blockIdx.x] = v;
    }
}
